{
  "findings": [
    {
      "check_id": "CKV_AZURE_10",
      "title": "MSSQL Security Alert Policy has disabled alerts for SQL Injection and Data Exfiltration",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "HIGH",
      "explanation": "The 'disabled_alerts' list explicitly turns off critical security alerts for 'Sql_Injection' and 'Data_Exfiltration', leaving the database vulnerable to these common attack vectors without notification."
    },
    {
      "check_id": "CKV_AZURE_11",
      "title": "MSSQL Security Alert Policy retention days is less than 90",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "LOW",
      "explanation": "The 'retention_days' is set to 20, which is below the recommended minimum of 90 days for audit log retention, potentially hindering long-term forensic analysis."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"alertpolicy6\" {\n  resource_group_name        = azurerm_resource_group.example.name\n  server_name                = azurerm_mssql_server.mssql6.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.security_storage_account.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.security_storage_account.primary_access_key\n  disabled_alerts = []\n  retention_days  = 90\n  email_addresses = [\"securityengineer@bridgecrew.io\"]\n}",
  "fix_summary": "Removed 'Sql_Injection' and 'Data_Exfiltration' from the 'disabled_alerts' list to ensure these critical threats are monitored. Increased 'retention_days' from 20 to 90 to meet standard compliance requirements for log retention."
}
